    let inner = Router::new().fallback(|| async { "inner" });
    let mid = Router::new().nest("/inner", inner);
    let app: Router = Router::new().nest("/mid", mid);

    let res = app
        .clone()
        .oneshot(Request::builder().uri("/mid/inner/foo").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.status(), 200);
}

